Engagement Service.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Engagement Service container

Container_Boundary(engagement_service, "Engagement Service") {
    Component(ReviewComponent, "Review Component", "Spring Boot (Java)", "Handles CRUD operations and OWASP input sanitization for user reviews.")
    Component(RecommendationComponent, "Recommendation Component", "Python / FastAPI", "Executes collaborative filtering models for product suggestions.")
}

Rel(ReviewComponent, RecommendationComponent, "Publishes ReviewSubmitted events to trigger recommendation updates", "Amazon SNS/SQS via HTTPS")

@enduml

Amazon Aurora PostgreSQL.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(amazon_aurora_postgresql, "Amazon Aurora PostgreSQL") {
    Component(AWS_RDS_Proxy, "AWS RDS Proxy", "AWS RDS Proxy", "Provides connection pooling and transaction management for database queries.")
    Component(Primary_Writer_Instance, "Primary Writer Instance", "PostgreSQL Engine", "Handles write operations and transactional updates for the database.")
    Component(Global_Read_Replicas, "Global Read Replicas", "PostgreSQL Engine", "Serves read traffic across global regions to ensure low-latency performance.")
    Component(Aurora_Distributed_Storage_Volume, "Aurora Distributed Storage Volume", "Amazon Aurora Storage", "Underlying distributed storage layer handling automated storage replication.")
}

Rel(AWS_RDS_Proxy, Primary_Writer_Instance, "Routes connection-pooled write queries via TCP", "TCP")
Rel(Primary_Writer_Instance, Global_Read_Replicas, "Replicates data via storage-level replication log stream", "Storage-level replication")

@enduml

Amazon OpenSearch.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(amazon_opensearch, "Amazon OpenSearch") {
    Component(Search Indexing Engine, "Search Indexing Engine", "Apache Lucene", "Handles the ingestion, indexing, and structural organization of catalogue data.")
    Component(Query Processing API, "Query Processing API", "REST / HTTPS", "Processes low-latency search queries received from the Catalog & Search container.")
}

Rel(Query Processing API, Search Indexing Engine, "Executes searches against")

@enduml

Message Bus.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(message_bus, "Message Bus") {
    Component(Event_Publisher, "Event Publisher", "AWS SNS Topics", "Handles fan-out messaging and broadcast of domain events.")
    Component(Event_Queue, "Event Queue", "AWS SQS Queues", "Provides reliable, durable queuing with SQS Long Polling.")
    Component(Schema_Validator, "Schema Validator", "Application-level validation", "Enforces JSON schema contracts before publishing.")
    Component(Dead_Letter_Queues, "Dead-Letter Queues", "AWS SQS DLQ", "Isolates and stores failed messages.")
    Component(Monitoring_Security_Controls, "Monitoring & Security Controls", "AWS KMS, IAM least-privilege, AWS CloudWatch, AWS CloudTrail", "Secures and monitors message bus operations and compliance.")
}

Rel(Schema_Validator, Event_Publisher, "Forwards validated domain events", "AWS Internal")
Rel(Event_Publisher, Event_Queue, "Fans out messages", "AWS Internal")
@enduml
